#!/usr/bin/env bash
# Autogenerated test: runs as the remote user inside a container built from each compatibility image with
# libvirt-in-docker installed with default options, after the entrypoint and the start check ran once.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib
# shellcheck source=/dev/null
source "$(dirname "$0")/helpers.sh"

check "virsh, virt-install, and qemu-img run" bash -c 'virsh --version && virt-install --version && qemu-img --version'
check "the QEMU system emulator of the container's architecture is installed" native_emulator_installed
check "a UEFI firmware image is installed" firmware_installed
check "swtpm is not installed by default, unless the distribution's QEMU driver depends on it" \
  swtpm_absent_unless_required
check "the entrypoint and the start check exist and are executable" test -x "${LID_START}" -a -x "${LID_CHECK}"
check "the container is privileged" container_is_privileged
check "the two volumes are mounted at /var/lib/libvirt and /etc/libvirt/qemu" \
  bash -c "grep -q ' /var/lib/libvirt ' /proc/self/mounts && grep -q ' /etc/libvirt/qemu ' /proc/self/mounts"
check "LIBVIRT_DEFAULT_URI is qemu:///system" test "${LIBVIRT_DEFAULT_URI:-}" = qemu:///system
check "the start check exits zero" "${LID_CHECK}"
check "the start record reports started daemons" test "$(record_field result)" = started
check "the start record says whether KVM is available" \
  bash -c 'record_field kvm | grep -q -x -E "available|unavailable"'
check "the start record is not writable by the remote user unless that user is root" \
  bash -c "test \"\$(id -u)\" = 0 || ! test -w ${LID_RECORD}"
check "the daemons of the distribution's layout and virtlogd run" layout_daemons_run
check "the remote user's default connection is qemu:///system" test "$(virsh uri)" = qemu:///system
check "the remote user lists guests without sudo" virsh list --all
check "the remote user lists storage pools and networks" bash -c 'virsh pool-list --all && virsh net-list --all'
check "the network default is active" network_is_active
check "the image's network default is not marked autostart" test "$(network_info Autostart)" = no
check "a software-emulated guest on the network default reaches the running state" start_emulated_guest network=default
check "the guest is removed" remove_guest
check "the feature's block stands at the top of /etc/libvirt/qemu.conf" block_first /etc/libvirt/qemu.conf
check "the image holds no libvirt-outside-of-docker" bash -c '! test -e /usr/local/share/libvirt-outside-of-docker'

reportResults
